#1 2 3#4 5 6#7 8 0GOAL = (1, 2, 3, 4, 5, 6, 7, 8, 0)MOVES = {    (-1, 0): 'UP',         (1, 0): 'DOWN',       (0, -1): 'LEFT',       (0, 1): 'RIGHT'    }def print_board(board):    for i in range(0, 9, 3):        print(f" {board[i]} {board[i+1]} {board[i+2]} ")    print("-" * 11)def depth_limited_search(state, path, visited, limit):    """Performs a standard Depth-Limited Search."""    if state == GOAL:        return path             if limit <= 0:        return None    blank = state.index(0)    r, c = blank // 3, blank % 3    for dr, dc in MOVES.keys():        nr, nc = r + dr, c + dc                     if 0 <= nr < 3 and 0 <= nc < 3:            neighbor = nr * 3 + nc                                 next_state = list(state)            next_state[blank], next_state[neighbor] = next_state[neighbor], next_state[blank]            next_tuple = tuple(next_state)            if next_tuple not in visited:                visited.add(next_tuple)                                                             result = depth_limited_search(next_tuple, path + [MOVES[(dr, dc)]], visited, limit - 1)                if result is not None:                    return result                                                 visited.remove(next_tuple)      return Nonedef iterative_deepening_search(start_state, max_depth=50):    """Repeatedly applies Depth-Limited Search with increasing depth thresholds."""    for depth in range(max_depth):               visited_states = {start_state}        result = depth_limited_search(start_state, [], visited_states, depth)                if result is not None:            return result, depth                return None, None# 1 2 3# 4 6 0# 7 5 8start = (1, 2, 3, 4, 6, 0, 7, 5, 8)solution, final_depth = iterative_deepening_search(start)if solution:    print("8 Puzzle using DFS ---\n")    print_board(start)    print(f"Solved at depth level: {final_depth}!")    print(f"Moves ({len(solution)} total): {' -> '.join(solution)}")    print(solution)else:    print("No solution found within the maximum depth threshold.")